    scanf("%d %d", &n, &m);

    int *deck = malloc((n+1) * sizeof(int));
    int *tmp = malloc((n+1) * sizeof(int));

    for (int i = 1; i <= n; i++) deck[i] = i;

    for (int i = 0; i < m; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        // New deck = deck[y+1..n], deck[x+1..y], deck[1..x]
        int idx = 1;
        for (int j = y+1; j <= n; j++) tmp[idx++] = deck[j];
        for (int j = x+1; j <= y; j++) tmp[idx++] = deck[j];
        for (int j = 1; j <= x; j++) tmp[idx++] = deck[j];
        // swap
        int *t = deck; deck = tmp; tmp = t;
    }

    int p, q, r;
    scanf("%d %d %d", &p, &q, &r);

    int count = 0;
    for (int i = p; i <= q; i++) {
        if (deck[i] <= r) count++;
    }

    printf("%d\n", count);

    free(deck);
    free(tmp);
    return 0;
}

