typedef long long ll;

typedef struct {
    ll l, r;   // positions interval
    ll add;    // value = position + add
} Seg;

typedef struct {
    Seg *a;
    int sz, cap;
} Vec;

static void vec_init(Vec *v) {
    v->sz = 0;
    v->cap = 8;
    v->a = (Seg*)malloc(sizeof(Seg) * v->cap);
}

static void vec_clear(Vec *v) {
    v->sz = 0;
}

static void vec_push(Vec *v, ll l, ll r, ll add) {
    if (l > r) return;
    if (v->sz && v->a[v->sz - 1].r + 1 == l && v->a[v->sz - 1].add == add) {
        v->a[v->sz - 1].r = r;
        return;
    }
    if (v->sz == v->cap) {
        v->cap <<= 1;
        v->a = (Seg*)realloc(v->a, sizeof(Seg) * v->cap);
    }
    v->a[v->sz].l = l;
    v->a[v->sz].r = r;
    v->a[v->sz].add = add;
    v->sz++;
}

static void split_at(Vec *v, ll pos) {
    if (pos <= 1) return;
    for (int i = 0; i < v->sz; i++) {
        if (v->a[i].l < pos && pos <= v->a[i].r) {
            Seg s = v->a[i];
            if (v->sz == v->cap) {
                v->cap <<= 1;
                v->a = (Seg*)realloc(v->a, sizeof(Seg) * v->cap);
            }
            for (int j = v->sz; j > i + 1; j--) v->a[j] = v->a[j - 1];
            v->a[i].r = pos - 1;
            v->a[i + 1].l = pos;
            v->a[i + 1].r = s.r;
            v->a[i + 1].add = s.add;
            v->sz++;
            return;
        }
    }
}

static ll count_leq_in_interval(ll l, ll r, ll add, ll R) {
    // count positions i in [l, r] such that i + add <= R
    ll t = R - add;
    if (t < l) return 0;
    if (t >= r) return r - l + 1;
    return t - l + 1;
}

int main() {
    ll n, m, p, q, r;
    if (scanf("%lld %lld %lld %lld %lld", &n, &m, &p, &q, &r) != 5) return 0;

    Vec cur, nxt;
    vec_init(&cur);
    vec_init(&nxt);

    // Initially card at position i has value i => add = 0
    vec_push(&cur, 1, n, 0);

    for (ll op = 0; op < m; op++) {
        ll x, y;
        scanf("%lld %lld", &x, &y);

        // New order: C, B, A
        // lengths: |A|=x, |B|=y-x, |C|=n-y
        split_at(&cur, x + 1);
        split_at(&cur, y + 1);

        vec_clear(&nxt);

        ll shiftC = -y;          // old [y+1..n] -> new [1..n-y]
        ll shiftB = n - y;       // old [x+1..y] -> new [n-y+1..n-x]
        ll shiftA = n - x;       // old [1..x]   -> new [n-x+1..n]

        for (int i = 0; i < cur.sz; i++) {
            Seg s = cur.a[i];
            if (s.r <= x) {
                vec_push(&nxt, s.l + shiftA, s.r + shiftA, s.add - shiftA);
            } else if (s.l > x && s.r <= y) {
                vec_push(&nxt, s.l + shiftB, s.r + shiftB, s.add - shiftB);
            } else { // s.l > y
                vec_push(&nxt, s.l + shiftC, s.r + shiftC, s.add - shiftC);
            }
        }

        Vec tmp = cur;
        cur = nxt;
        nxt = tmp;
    }

    split_at(&cur, p);
    split_at(&cur, q + 1);

    ll ans = 0;
    for (int i = 0; i < cur.sz; i++) {
        ll l = cur.a[i].l, rr = cur.a[i].r, add = cur.a[i].add;
        if (rr < p || l > q) continue;
        if (l < p) l = p;
        if (rr > q) rr = q;
        ans += count_leq_in_interval(l, rr, add, r);
    }

    printf("%lld\n", ans);
    return 0;
}

