public class ShuffleProblem {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int p = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());

        int[][] shuffles = new int[m][2];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            shuffles[i][0] = Integer.parseInt(st.nextToken());
            shuffles[i][1] = Integer.parseInt(st.nextToken());
        }

        int count = 0;
        for (int pos = p; pos <= q; pos++) {
            int currentPos = pos;
            // Reverse the shuffles
            for (int i = m - 1; i >= 0; i--) {
                int x = shuffles[i][0];
                int y = shuffles[i][1];
                int lenC = n - y;
                if (currentPos <= lenC) {
                    // came from C (positions y+1 .. n)
                    currentPos = y + currentPos;
                } else if (currentPos <= lenC + (y - x)) {
                    // came from B (positions x+1 .. y)
                    currentPos = x + (currentPos - lenC);
                } else {
                    // came from A (positions 1 .. x)
                    currentPos = currentPos - (lenC + (y - x));
                }
            }
            if (currentPos <= r) count++;
        }

        System.out.println(count);
    }
}

