public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        // deck as list of [start, end] segments (1-indexed card values, contiguous)
        List<long[]> deck = new ArrayList<>();
        deck.add(new long[]{1, n});

        int m = Integer.parseInt(br.readLine().trim());
        for (int i = 0; i < m; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            // Split into A (pos 1..x), B (pos x+1..y), C (pos y+1..n)
            List<long[]> A = extract(deck, 1, x);
            List<long[]> B = extract(deck, x+1, y);
            List<long[]> C = extract(deck, y+1, (int)(totalSize(deck)));
            deck = new ArrayList<>();
            deck.addAll(C); deck.addAll(B); deck.addAll(A);
        }

        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());

        // Count cards in positions p..q with value <= r
        List<long[]> sub = extract(deck, p, q);
         long count = 0;
        for (long[] seg : sub) {
            long lo = seg[0], hi = seg[1];
            long overlapLo = Math.max(lo, 1);
            long overlapHi = Math.min(hi, r);
            if (overlapHi >= overlapLo) count += overlapHi - overlapLo + 1;
        }
        System.out.println(count);
    }

    static long totalSize(List<long[]> deck) {
        long s = 0;
        for (long[] seg : deck) s += seg[1] - seg[0] + 1;
        return s;
    }

    static List<long[]> extract(List<long[]> deck, long from, long to) {
        List<long[]> result = new ArrayList<>();
        long pos = 0;
        for (long[] seg : deck) {
            long sz = seg[1] - seg[0] + 1;
            long segStart = pos + 1, segEnd = pos + sz;
            long lo = Math.max(segStart, from), hi = Math.min(segEnd, to);
            if (lo <= hi) {
                long offset = lo - segStart;
                result.add(new long[]{seg[0] + offset, seg[0] + offset + (hi - lo)});
            }
            pos += sz;
        }
        return result;
    }
}

