public class Main {
    // Implicit treap storing current deck order.
    // Each node represents one card value.
    static class Node {
        int val, prio, sz;
        Node l, r;
        int min, max; // min/max card value in subtree
        Node(int v, int p) {
            val = v;
            prio = p;
            sz = 1;
            min = max = v;
        }
    }

    static final Random rng = new Random(1);

    static int size(Node t) {
        return t == null ? 0 : t.sz;
    }

    static int minVal(Node t) {
        return t == null ? Integer.MAX_VALUE : t.min;
    }

    static int maxVal(Node t) {
        return t == null ? Integer.MIN_VALUE : t.max;
    }

    static void pull(Node t) {
        if (t == null) return;
        t.sz = 1 + size(t.l) + size(t.r);
        t.min = Math.min(t.val, Math.min(minVal(t.l), minVal(t.r)));
        t.max = Math.max(t.val, Math.max(maxVal(t.l), maxVal(t.r)));
    }

    // Split by first k elements: returns [a,b] where a has first k elements.
    static Node[] split(Node t, int k) {
        if (t == null) return new Node[]{null, null};
        if (size(t.l) >= k) {
            Node[] res = split(t.l, k);
            t.l = res[1];
            pull(t);
            return new Node[]{res[0], t};
        } else {
            Node[] res = split(t.r, k - size(t.l) - 1);
            t.r = res[0];
            pull(t);
            return new Node[]{t, res[1]};
        }
    }

    static Node merge(Node a, Node b) {
        if (a == null) return b;
        if (b == null) return a;
        if (a.prio > b.prio) {
            a.r = merge(a.r, b);
            pull(a);
            return a;
        } else {
            b.l = merge(a, b.l);
            pull(b);
            return b;
        }
    }

    // Count in subtree how many values <= r.
    // Uses pruning because each subtree always contains a contiguous set of original values,
    // hence min/max fully determine whether whole subtree qualifies or not.
    static int countLE(Node t, int r) {
        if (t == null) return 0;
        if (t.min > r) return 0;
        if (t.max <= r) return t.sz;
        int ans = (t.val <= r ? 1 : 0);
        ans += countLE(t.l, r);
        ans += countLE(t.r, r);
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        int p = fs.nextInt();
        int q = fs.nextInt();
        int r = fs.nextInt();

        Node root = null;
        for (int i = 1; i <= n; i++) {
            root = merge(root, new Node(i, rng.nextInt()));
        }

        for (int i = 0; i < m; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();

            // Deck = [1..x] [x+1..y] [y+1..n] as positions in current deck
            // After shuffle(x,y): [y+1..n] [x+1..y] [1..x]
            Node[] s1 = split(root, x);
            Node A = s1[0], rest = s1[1];
            Node[] s2 = split(rest, y - x);
            Node B = s2[0], C = s2[1];
            root = merge(C, merge(B, A));
        }

        // Extract positions [p..q]
        Node[] t1 = split(root, p - 1);
        Node left = t1[0], rest = t1[1];
        Node[] t2 = split(rest, q - p + 1);
        Node mid = t2[0], right = t2[1];

        int ans = countLE(mid, r);
        System.out.println(ans);

        // Optional restore not needed
        // root = merge(left, merge(mid, right));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

