#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Op {
    int64 x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, p, q, r;
    cin >> n >> m >> p >> q >> r;

    vector<Op> ops(m);
    for (int i = 0; i < m; ++i) cin >> ops[i].x >> ops[i].y;

    // We need count of final positions i in [p, q] whose card number <= r.
    // Equivalently, for each final position i, let f(i) be original position/card number.
    // Count i in [p,q] with f(i) <= r.
    //
    // For one shuffle(x,y), with lengths:
    // A = [1..x], B = [x+1..y], C = [y+1..n]
    // New deck order is C B A.
    //
    // Mapping old position -> new position:
    // old in A: pos' = (n - x) + old
    // old in B: pos' = (n - y) + (old - x)
    // old in C: pos' = old - y
    //
    // We process final interval [p,q] backwards through inverse shuffles to obtain
    // a set of original intervals. Since each inverse shuffle maps an interval into
    // at most 3 intervals, but all breakpoints are only from operation boundaries,
    // we maintain disjoint merged intervals. Number stays manageable for constraints
    // intended by this problem style.

    vector<pair<int64,int64>> segs = {{p, q}}; // intervals in current deck positions

    auto addSeg = [&](vector<pair<int64,int64>>& v, int64 l, int64 rr) {
        if (l > rr) return;
        v.push_back({l, rr});
    };

    for (int i = m - 1; i >= 0; --i) {
        int64 x = ops[i].x, y = ops[i].y;
        int64 lenC = n - y;
        int64 lenB = y - x;
        int64 lenA = x;

        vector<pair<int64,int64>> nxt;

        for (auto [l, rr] : segs) {
            // In new deck:
            // C occupies [1 .. lenC]         -> old [y+1 .. n] by +y
            // B occupies [lenC+1 .. lenC+lenB] -> old [x+1 .. y] by -lenC + x
            // A occupies [lenC+lenB+1 .. n]  -> old [1 .. x] by -(lenC+lenB)

            // Part in C block
            int64 L = max<int64>(l, 1);
            int64 R = min<int64>(rr, lenC);
            if (L <= R) addSeg(nxt, L + y, R + y);

            // Part in B block
            L = max<int64>(l, lenC + 1);
            R = min<int64>(rr, lenC + lenB);
            if (L <= R) addSeg(nxt, L - lenC + x, R - lenC + x);

            // Part in A block
            L = max<int64>(l, lenC + lenB + 1);
            R = min<int64>(rr, n);
            if (L <= R) addSeg(nxt, L - (lenC + lenB), R - (lenC + lenB));
        }

        if (nxt.empty()) {
            segs.clear();
            break;
        }

        sort(nxt.begin(), nxt.end());
        segs.clear();
        for (auto [l, rr] : nxt) {
            if (segs.empty() || segs.back().second + 1 < l) segs.push_back({l, rr});
            else segs.back().second = max(segs.back().second, rr);
        }
    }

    int64 ans = 0;
    for (auto [l, rr] : segs) {
        int64 L = max<int64>(l, 1);
        int64 R = min<int64>(rr, r);
        if (L <= R) ans += R - L + 1;
    }

    cout << ans << '\n';
    return 0;
}
